// Standalone branded gate: no assets can be fetched before the entrance key is accepted.
const esc = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function gatePage({ next = "/", error = "" } = {}) {
return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>Welcome to 2x2</title><style>
*{box-sizing:border-box}body{margin:0;background:#e6e6ed;color:#2b243c;font:14px/1.5 Arial,sans-serif}body::before{content:"";display:block;height:58px;background:linear-gradient(90deg,#40218f,#6931ad);border-bottom:3px solid #2cd9e4}.wrap{max-width:400px;margin:6vh auto 30px;padding:0 16px}.brand{text-align:center}.brand img{width:150px;height:150px;filter:drop-shadow(0 5px 0 #613b9b22)}form{margin-top:25px;background:white;border:1px solid #cecbdc;border-top:3px solid #d62ae6;padding:25px;box-shadow:0 2px 3px #21113915}h1{font-size:22px;margin:0 0 8px}p{color:#70677d;margin:0 0 20px}label{display:block;font-weight:bold;margin-bottom:7px}input{width:100%;padding:10px;border:1px solid #c9c5d4;border-radius:2px;font:inherit}input:focus{outline:2px solid #9863cf;outline-offset:1px}button{padding:10px 18px;border:1px solid #48248f;border-bottom-width:3px;border-radius:3px;background:#683ac7;color:white;font:bold 14px Arial;cursor:pointer;margin-top:18px;width:100%}button:hover{background:#7b49dc}.err{color:#b52959}.foot{text-align:center;font-size:11px;margin-top:18px}
</style></head><body><div class="wrap"><div class="brand"><img src="data:image/png;base64," alt="2x2" width="150" height="150"></div><form method="post" action="/__gate" autocomplete="off"><h1>Welcome to 2x2.</h1><p>Enter your entrance key to come in.</p>${error ? `<p class="err" role="alert">${esc(error)}</p>` : ""}<label for="token">Entrance key</label><input id="token" name="token" type="password" required autofocus><input type="hidden" name="next" value="${esc(next)}"><button type="submit">Enter 2x2</button></form><p class="foot">Classic places. New memories.</p></div></body></html>`;
}
